    function previewMetrics(viewportWidth,logicalWidth,zoom=1,height=600){
        const width=Math.max(240,Math.min(2400,Number(logicalWidth)||viewportWidth));const scale=Math.max(.1,Math.min(3,Number(zoom)||1));
        return {width,scale,height:Math.max(300,Math.min(30000,Number(height)||600)),scaledWidth:width*scale,scaledHeight:Math.max(300,Math.min(30000,Number(height)||600))*scale};
    }
