        overlay.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>{const action=b.dataset.action;if(action==='close')return closeMintFullscreen();if(action==='fit')fit=true;else{fit=false;scale+=(action==='plus'?0.1:-0.1);}paint();}));widthInput.addEventListener('change',()=>{contentHeight=800;paint();});
