    async function receiveGeneration(promise, signal) {
        let timer, abort;
        const stop = new Promise((_, reject) => {
            abort = () => reject(new Error('已取消接收生成结果'));
            if (signal.aborted) return abort();
            signal.addEventListener('abort', abort, { once: true });
            timer = setTimeout(() => { generationController?.abort(); reject(new Error('生成等待超过 4 分钟')); }, 240000);
        });
        try { return await Promise.race([promise, stop]); }
        finally { clearTimeout(timer); signal.removeEventListener('abort', abort); }
    }
