    function switchMintPage(panel, page, announce = true) {
        if (!['create','gallery','history','settings'].includes(page)) return;
        const scroll = panel.querySelector('#mint-scroll');
        pageScroll.set(currentPage, scroll.scrollTop); currentPage = page;
        panel.querySelectorAll('[data-mint-page]').forEach(section => { section.hidden = section.dataset.mintPage !== page; });
        panel.querySelectorAll('[data-page]').forEach(button => { button.setAttribute('aria-selected',String(button.dataset.page === page)); button.tabIndex = button.dataset.page === page ? 0 : -1; });
        scroll.scrollTop = pageScroll.get(page) || 0;
        if(page==='gallery'){renderRemoteGallery(panel).catch(e=>toast(e.message,'error'));renderImagePlan(panel).catch(e=>toast(e.message,'error'));}
        if(page==='settings')updateConnectionOverview(panel);
        if (page === 'history') renderHistory(panel).catch(e => toast(e.message,'error'));
        if (announce && uiPrefs.showPageNotices) showCapsule(({create:'回到创作台',gallery:'打开图片收藏室',history:'打开灵感存档',settings:'打开设置'})[page]);
    }
